for src, quote, num, text in CLAIMS:
    r = subprocess.run(["python3", "tools/rychag.py", "claim", "add", "--project", "megafon-app", "--type", "calc", "--source", src, "--quote", quote, "--number", num, "--text", text], capture_output=True, text=True)
    print((r.stdout + r.stderr).strip().splitlines()[-1][:160])
